import{z as i,x as s,o as A,c as d,q as t,j as r,D as a,d as B,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"复现案例：推理引擎","description":"","frontmatter":{"title":"复现案例：推理引擎","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-case-inference.md","filePath":"llm/rw-case-inference.md","lastUpdated":1791063341000}'),p={name:"llm/rw-case-inference.md"};function m(D,E,f,h,c,C){const l=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="复现案例-推理引擎" tabindex="-1">复现案例：推理引擎 <a class="header-anchor" href="#复现案例-推理引擎" aria-label="Permalink to &quot;复现案例：推理引擎&quot;">​</a></h1><div class="epigraph"><p>系统论文要证明的常常不是想法可行，而是想法在大规模下仍然可行；所以它的每个数字都绑着一份负载。</p><footer>—— 据 Kwon 等, Efficient Memory Management for LLM Serving with PagedAttention, SOSP 2023 整理</footer></div><p><a href="/llm/rw-report-writing">上一课</a>给了报告骨架，本课把它放进第一个完整案例：把一篇推理系统论文复现成引擎里可验证的特性。以 PagedAttention 一系的口径为锚——分页 KV 管理、连续批处理、吞吐倍数声称。框架走读课（<a href="/llm/fw-vllm-walkthrough">fw-vllm-walkthrough</a>）已经解剖过这类引擎的骨架，本课不复读架构，只走复现工作流在这类论文上的特殊形态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>系统论文的复现与训练论文不同，坐标系里多出三个维度：负载（请求长度分布、到达间隔）、调度（批组合与时机）、硬件（卡型与互联）。论文声称的吞吐倍数绑定在这三个维度上——换了负载分布，「3 倍吞吐」没有语义。更麻烦的是锚点换型：训练论文有 loss 可对账，推理论文没有；正确的锚点从「一步的训练」换成「一步的调度」——引擎在一个调度决策里做了什么选择、写下了哪些分配。找不到这个锚点，性能对比会退化成跑分：你的实现输给参考实现时，无法区分是想法错了还是工程差了。</p><p><span class="marginnote">「PagedAttention」的思路是把显存当内存管：像操作系统分页管理内存那样，把 KV 缓存切成固定大小的「页」按需分配，不再要求一整块连续空间。浪费少了、能塞的请求多了，「3 倍吞吐」这类声称就绑在这个机制上，也因此绑着负载。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按第一课定类型：系统论文常是混合型——正确性走结果复现（同代码同负载重放出同曲线），性能结论走方法复现（独立实现复出相对基线的倍数）。走读按三步法找锚点：入口、一步调度的产出物（这步接了哪些请求、分配了哪些块、抢占了谁）、沿块表到内核。正确性锚点分层：第一层是贪心解码下的输出对齐——温度取零，请求级对比参考实现的 token 序列；第二层是 logit 级相对误差——批大小与内核不同会改变浮点求和次序，逐 token 完全一致不是可靠判据（见边界）。性能锚点是负载重放：记录请求序列（长度、到达时间戳），在两个实现上重放同一条序列；吞吐、时延分位数、显存峰值都从重放读出，而不是从各自独立压测读出。</p><p><span class="marginnote">数字实例：一份重放序列可能长这样——「1000 条请求，长度均匀取自 200 到 2000 token，泊松到达、平均每秒 8 条」。两个引擎读同一份序列文件、按同一时间戳发请求，测出来的吞吐差才只反映引擎本身，而不是谁碰巧撞上了一批短请求。</span></p>',9)),(A(),r(o,null,{default:a(()=>[n(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAPER%5B%22%E7%B3%BB%E7%BB%9F%E8%AE%BA%E6%96%87%EF%BC%9A%E5%90%9E%E5%90%90%E5%80%8D%E6%95%B0%22%5D%20--%3E%20TYPE%5B%22%E7%B1%BB%E5%9E%8B%EF%BC%9A%E6%AD%A3%E7%A1%AE%E6%80%A7%E7%BB%93%E6%9E%9C%E5%A4%8D%E7%8E%B0%2B%E6%80%A7%E8%83%BD%E6%96%B9%E6%B3%95%E5%A4%8D%E7%8E%B0%22%5D%0A%20%20TYPE%20--%3E%20WALK%5B%22%E8%B5%B0%E8%AF%BB%EF%BC%9A%E4%B8%80%E6%AD%A5%E8%B0%83%E5%BA%A6%E7%9A%84%E4%BA%A7%E5%87%BA%E7%89%A9%22%5D%0A%20%20WALK%20--%3E%20CORR%5B%22%E6%AD%A3%E7%A1%AE%E6%80%A7%E9%94%9A%E7%82%B9%EF%BC%9A%E8%B4%AA%E5%BF%83%E8%BE%93%E5%87%BA%2Blogit%20%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20CORR%20--%3E%20REPLAY%5B%22%E8%B4%9F%E8%BD%BD%E9%87%8D%E6%94%BE%EF%BC%9A%E5%90%8C%E8%AF%B7%E6%B1%82%E5%BA%8F%E5%88%97%22%5D%0A%20%20REPLAY%20--%3E%20METRICS%5B%22%E5%90%9E%E5%90%90%2F%E6%97%B6%E5%BB%B6%E5%88%86%E4%BD%8D%2F%E6%98%BE%E5%AD%98%E5%B3%B0%E5%80%BC%22%5D%0A%20%20METRICS%20--%3E%20REPORT%5B%22%E6%8A%A5%E5%91%8A%EF%BC%9A%E5%9D%90%E6%A0%87%E7%B3%BB%E5%90%AB%E8%B4%9F%E8%BD%BD%E4%B8%8E%E7%A1%AC%E4%BB%B6%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[B("为什么负载重放是性能对齐的核心：压测吞吐的方差来源——请求长度分布、到达突发、缓存冷热——全部由序列决定；序列相同，两个实现的差异才只剩调度与内核本身。这也是「3 倍」这类倍数声称的正确读法：倍数绑定在论文的重放序列上，你用自己的负载测出的倍数不同，不是复现失败，是坐标系不同（判读一课的口径）。为什么微基准补位端到端：显存碎片率、块利用率这类量在端到端曲线里不可见，用固定请求序列的受控微基准（页大小扫描、并发度扫描）把机制量单独读出来，才能归因到「分页省了显存」而不是「实现了别的什么也省了」。性能回归的防漂移纪律——同机同时段 A/B、多次重复取分布——沿用"),e("a",{href:"/llm/fw-perf-regression"},"性能回归的方法"),B("。")],-1)),(A(),r(o,null,{default:a(()=>[n(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E9%87%8D%E6%94%BE%E5%BA%8F%E5%88%97%EF%BC%9A%E9%95%BF%E5%BA%A6%E5%8A%A0%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%20--%3E%20V1%5B%22%E8%B4%9F%E8%BD%BD%E6%96%B9%E5%B7%AE%EF%BC%9A%E8%A2%AB%E5%BA%8F%E5%88%97%E5%86%BB%E7%BB%93%22%5D%0A%20%20SEQ%20--%3E%20V2%5B%22%E5%88%B0%E8%BE%BE%E7%AA%81%E5%8F%91%EF%BC%9A%E8%A2%AB%E5%BA%8F%E5%88%97%E5%86%BB%E7%BB%93%22%5D%0A%20%20SEQ%20--%3E%20V3%5B%22%E7%BC%93%E5%AD%98%E5%86%B7%E7%83%AD%EF%BC%9A%E8%A2%AB%E5%BA%8F%E5%88%97%E5%86%BB%E7%BB%93%22%5D%0A%20%20SEQ%20--%3E%20L1%5B%22%E5%89%A9%E4%B8%8B%E7%9A%84%E5%B7%AE%E5%BC%82%EF%BC%9A%E8%B0%83%E5%BA%A6%E7%AD%96%E7%95%A5%22%5D%0A%20%20SEQ%20--%3E%20L2%5B%22%E5%89%A9%E4%B8%8B%E7%9A%84%E5%B7%AE%E5%BC%82%EF%BC%9A%E5%86%85%E6%A0%B8%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20L1%20--%3E%20OUT%5B%22%E5%90%9E%E5%90%90%E4%B8%8E%E6%97%B6%E5%BB%B6%E5%B7%AE%20%3D%20%E6%83%B3%E6%B3%95%E4%B8%8E%E5%B7%A5%E7%A8%8B%E5%90%84%E8%87%AA%E7%9A%84%E8%B4%A6%22%5D%0A%20%20L2%20--%3E%20OUT%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：拿自己 A100 上的绝对吞吐去对比论文里 H100 的数字，然后宣布「复现失败」。不同卡型的绝对值不可比，正文给的做法是只比「相对基线的倍数」，并把卡型与互联写进坐标系。</span></p><p><span class="marginnote">贪心解码的「逐 token 完全一致」会误报：批大小改变 GEMM 形状，浮点归约次序随之改变，两个并列概率的 token 可能交换 argmax。稳定判据是 top-2 概率差加阈值，或者只比高置信段的序列——把浮点次序效应排除在「错误」之外。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>案例不覆盖服务级语义：SLO 分层、抢占公平性、多租户隔离是调度与多租户课程的主题，复现到「机制量对齐」即止。硬件坐标要诚实：不同卡型的吞吐绝对值不可比，跨硬件只报告相对基线的倍数并附绝对值坐标；内核差异（专用实现与通用实现）与算法差异（调度策略）要在报告里拆开，混写会让「复现了想法」变成「复现了某个工程组合」。最后一，复现产物按上一课骨架落档，性能判定同样挂 run——负载序列的哈希是坐标系的一部分，与数据指纹同级。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>系统论文复现的坐标系多三维：负载、调度、硬件；倍数声称绑定负载重放。</li><li>锚点从 loss 换成一步调度的产出物；正确性用贪心输出加 logit 误差，不用逐 token 完全一致。</li><li>负载重放隔离实现差异：同序列之下，差异只剩调度与内核。</li><li>微基准读机制量（碎片率、块利用率），端到端只出验收判定。</li><li>出处：Kwon 等, SOSP 2023；走读见<a href="/llm/fw-vllm-walkthrough">fw-vllm-walkthrough</a>；防漂移见<a href="/llm/fw-perf-regression">性能回归的方法</a>。</li></ul>',6))])}const g=i(p,[["render",m]]);export{u as __pageData,g as default};
